/*'use client';

import { useState, useEffect } from 'react';
import { useRouter } from 'next/navigation';
import { db } from '@/lib/firebase';
import { addDoc, collection, serverTimestamp, query, getDocs } from 'firebase/firestore';
import { v4 as uuidv4 } from 'uuid';
import { faMicrophone, faMicrophoneSlash, faVideo, faVideoSlash, faLaptop, faPhone, faSmile, faUserCircle } from '@fortawesome/free-solid-svg-icons';
import { FontAwesomeIcon } from '@fortawesome/react-fontawesome';

export default function RoomPage() {
  const router = useRouter();
  const [roomName, setRoomName] = useState('');
  const [limit, setLimit] = useState<number | undefined>(undefined);
  const [objective, setObjective] = useState('');
  const [participantEmails, setParticipantEmails] = useState('');
  const [visibility, setVisibility] = useState<'public' | 'private'>('public');
  
  const [micStatus, setMicStatus] = useState<'on' | 'off'>('off');
  const [cameraStatus, setCameraStatus] = useState<'on' | 'off'>('off');
  
  const [existingRooms, setExistingRooms] = useState<any[]>([]);
  const [selectedRoomId, setSelectedRoomId] = useState<string | null>(null);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    const fetchRooms = async () => {
      const q = query(collection(db, 'rooms'));
      const querySnapshot = await getDocs(q);
      const rooms: any[] = [];
      querySnapshot.forEach((doc) => {
        rooms.push({ id: doc.id, name: doc.data().name });
      });
      setExistingRooms(rooms);
    };

    fetchRooms();
  }, []);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    // Validation before creating room
    if (!roomName || !objective) {
      setError('Room name and objective are required.');
      return;
    }
    
    const roomId = `${roomName.toLowerCase().replace(/\s+/g, '-')}-${uuidv4().substring(0, 5)}`; // Create unique room ID
    
    try {
      await addDoc(collection(db, 'rooms'), {
        id: roomId,
        name: roomName,
        limit: limit || null,
        objective,
        visibility,
        participantEmails: participantEmails
          ? participantEmails.split(',').map((email) => email.trim())
          : [],
        micStatus,
        cameraStatus,
        createdAt: serverTimestamp(),
      });

      router.push(`/coworking/${roomId}?mic=${micStatus}&camera=${cameraStatus}`);
    } catch (error) {
      console.error('Error creating room:', error);
      setError('Failed to create room, please try again.');
    }
  };

  const handleJoinRoom = async () => {
    if (!selectedRoomId) return;

    router.push(`/coworking/${selectedRoomId}?mic=${micStatus}&camera=${cameraStatus}`);
  };

  return (
    <div className='flex   bg-amber-50 text-black '>
    <div className='flex-1 '>
         <div className="flex space-x-4">
          <div>
             <div className="flex space-x-4">
                        <button onClick={toggleMic} className="bg-gray-400 text-white p-3 rounded-full flex items-center">
                            <FontAwesomeIcon icon={isMicOn ? faMicrophone : faMicrophoneSlash} className="w-6 h-6" />
                        </button>  
                        <button onClick={toggleCamera} className="bg-gray-400 text-white p-3 rounded-full ">
                            <FontAwesomeIcon icon={isCameraOn ? faVideo : faVideoSlash} className="w-6 h-6" />
                        </button>
            </div>
          </div>

          <div>
            <label className="block">Camera</label>
            <div className="space-x-4">
              <label>
                <input
                  type="radio"
                  name="cameraStatus"
                  value="on"
                  checked={cameraStatus === 'on'}
                  onChange={() => setCameraStatus('on')}
                />
                <FontAwesomeIcon icon={faVideo} className="ml-2" /> On
              </label>
              <label>
                <input
                  type="radio"
                  name="cameraStatus"
                  value="off"
                  checked={cameraStatus === 'off'}
                  onChange={() => setCameraStatus('off')}
                />
                <FontAwesomeIcon icon={faVideoSlash} className="ml-2" /> Off
              </label>
            </div>
          </div>
        </div>

    </div>
    <div className=" flex-1 space-y-4">
      <h1 className="text-2xl font-bold mb-4">Create or Join a Room</h1>

      {error && <div className="text-red-500">{error}</div>}

      <div className="space-y-4">
        <h2 className="text-lg font-medium">Join an Existing Room</h2>
        <select
          value={selectedRoomId || ''}
          onChange={(e) => setSelectedRoomId(e.target.value)}
          className="w-full p-2 border rounded"
        >
          <option value="">Select a Room</option>
          {existingRooms.map((room) => (
            <option key={room.id} value={room.id}>
              {room.name}
            </option>
          ))}
        </select>
        <button
          onClick={handleJoinRoom}
          disabled={!selectedRoomId}
          className="w-full bg-blue-600 text-white py-2 rounded disabled:bg-gray-400"
        >
          Join Room
        </button>
      </div>

    
      <form onSubmit={handleSubmit} className="space-y-4">
        <h2 className="text-lg font-medium">Create a New Room</h2>

        <input
          type="text"
          placeholder="Room Name"
          value={roomName}
          onChange={(e) => setRoomName(e.target.value)}
          required
          className="w-full p-2 border rounded"
        />

        <input
          type="number"
          placeholder="Limit of Participants (optional)"
          value={limit || ''}
          onChange={(e) => setLimit(Number(e.target.value))}
          className="w-full p-2 border rounded"
        />

        <input
          type="text"
          placeholder="Objective (e.g., Study, Meeting)"
          value={objective}
          onChange={(e) => setObjective(e.target.value)}
          required
          className="w-full p-2 border rounded"
        />

        <input
          type="text"
          placeholder="Participant Emails (comma separated)"
          value={participantEmails}
          onChange={(e) => setParticipantEmails(e.target.value)}
          className="w-full p-2 border rounded"
        />

        <select
          value={visibility}
          onChange={(e) => setVisibility(e.target.value as 'public' | 'private')}
          className="w-full p-2 border rounded"
        >
          <option value="public">Public</option>
          <option value="private">Private</option>
        </select>

       
        <button type="submit" className="w-full bg-blue-600 text-white py-2 rounded">
          Create Room
        </button>
      </form>
    </div>
    </div> 
  );
}
*/// app/join-room/page.tsx
'use client';

import React, { useEffect, useRef, useState } from 'react';
import { useRouter } from 'next/navigation';
import { FontAwesomeIcon } from '@fortawesome/react-fontawesome';
import {
  faMicrophone,
  faMicrophoneSlash,
  faVideo,
  faVideoSlash,
  faEllipsisH,
  faCopy
} from '@fortawesome/free-solid-svg-icons';

export default function JoinRoomPage() {
  const videoRef = useRef<HTMLVideoElement>(null);
  const [username, setUsername] = useState('');
  const [micOn, setMicOn] = useState(true);
  const [cameraOn, setCameraOn] = useState(true);
  const [roomId] = useState(() => {
    // you could generate or fetch this dynamically
    // for demo we hardcode or derive from URL
    return '8d5325ca-e4f1-4a7c-9e1e-123456789abc';
  });
  const router = useRouter();

  // start/stop tracks based on toggles
  useEffect(() => {
    let stream: MediaStream;
    (async () => {
      if (videoRef.current) {
        try {
          stream = await navigator.mediaDevices.getUserMedia({
            video: cameraOn,
            audio: micOn
          });
          videoRef.current.srcObject = stream;
        } catch (e) {
          console.error('could not get media', e);
        }
      }
    })();
    return () => {
      stream?.getTracks().forEach((t) => t.stop());
    };
  }, [micOn, cameraOn]);

  const handleJoin = () => {
    if (!username.trim()) return;
    router.push(`/videoCall/${roomId}?user=${encodeURIComponent(username)}`);
  };

  const shareLink = `${typeof window !== 'undefined' ? window.location.origin : ''}/videoCall/${roomId}`;
  const copyLink = () => {
    navigator.clipboard.writeText(shareLink);
  };

  return (
    <div className="flex h-screen bg-gray-100">
      {/* Left: Video Preview */}
      <div className="flex-1 flex flex-col bg-white m-6 rounded-2xl overflow-hidden shadow-lg">
        <video
          ref={videoRef}
          autoPlay
          muted
          playsInline
          className="w-full h-full object-cover bg-black"
        />
        <div className="flex justify-center space-x-6 bg-gray-800 p-4">
          <button
            onClick={() => setMicOn((m) => !m)}
            className="p-3 rounded-full bg-gray-700 text-white hover:bg-gray-600"
          >
            <FontAwesomeIcon icon={micOn ? faMicrophone : faMicrophoneSlash} />
          </button>
          <button
            onClick={() => setCameraOn((c) => !c)}
            className="p-3 rounded-full bg-gray-700 text-white hover:bg-gray-600"
          >
            <FontAwesomeIcon icon={cameraOn ? faVideo : faVideoSlash} />
          </button>
          <button className="p-3 rounded-full bg-gray-700 text-white hover:bg-gray-600">
            <FontAwesomeIcon icon={faEllipsisH} />
          </button>
        </div>
      </div>

      <div className="space-y-4">
        <h2 className="text-lg font-medium">Join an Existing Room</h2>
        <select
          value={selectedRoomId || ''}
          onChange={(e) => setSelectedRoomId(e.target.value)}
          className="w-full p-2 border rounded"
        >
          <option value="">Select a Room</option>
          {existingRooms.map((room) => (
            <option key={room.id} value={room.id}>
              {room.name}
            </option>
          ))}
        </select>
        <button
          onClick={handleJoinRoom}
          disabled={!selectedRoomId}
          className="w-full bg-blue-600 text-white py-2 rounded disabled:bg-gray-400"
        >
          Join Room
        </button>
      </div>

    
      <form onSubmit={handleSubmit} className="space-y-4">
        <h2 className="text-lg font-medium">Create a New Room</h2>

        <input
          type="text"
          placeholder="Room Name"
          value={roomName}
          onChange={(e) => setRoomName(e.target.value)}
          required
          className="w-full p-2 border rounded"
        />

        <input
          type="number"
          placeholder="Limit of Participants (optional)"
          value={limit || ''}
          onChange={(e) => setLimit(Number(e.target.value))}
          className="w-full p-2 border rounded"
        />

        <input
          type="text"
          placeholder="Objective (e.g., Study, Meeting)"
          value={objective}
          onChange={(e) => setObjective(e.target.value)}
          required
          className="w-full p-2 border rounded"
        />

        <input
          type="text"
          placeholder="Participant Emails (comma separated)"
          value={participantEmails}
          onChange={(e) => setParticipantEmails(e.target.value)}
          className="w-full p-2 border rounded"
        />

        <select
          value={visibility}
          onChange={(e) => setVisibility(e.target.value as 'public' | 'private')}
          className="w-full p-2 border rounded"
        >
          <option value="public">Public</option>
          <option value="private">Private</option>
        </select>

       
        <button type="submit" className="w-full bg-blue-600 text-white py-2 rounded">
          Create Room
        </button>
      </form>
        </div>
      
    
  );
}
